#!/usr/bin/env node
/**
 * Builds the publishable `lody-code-review-viewer` package:
 *
 *   - copies the single-file viewer built by `@lody/code-review-helper`
 *     (`dist-standalone/standalone.html`) to this package root as `standalone.html`
 *     (this is what jsDelivr serves and what the `lody` CLI downloads), and
 *   - generates `dist/manifest.generated.ts` with the package version + the
 *     sha256 of `standalone.html`. The `lody` CLI imports this manifest at build
 *     time so it can fetch the EXACT matching viewer version and verify its hash.
 *
 * Invariant: the sha256 in the manifest is the hash of the exact `standalone.html`
 * shipped in this package, so a CLI built against this package always verifies the
 * file jsDelivr serves for this version. Published packages keep this version in
 * lockstep with `lody` so the pinned viewer is always available.
 */
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const helperHtml = path.resolve(
  packageRoot,
  '../code-review-helper/dist-standalone/standalone.html'
);

let html;
try {
  html = readFileSync(helperHtml);
} catch {
  throw new Error(
    `Viewer source not found at ${helperHtml}. ` +
      'Run `pnpm --filter @lody/code-review-helper build:standalone` first.'
  );
}

const outHtml = path.join(packageRoot, 'standalone.html');
writeFileSync(outHtml, html);

const sha256 = createHash('sha256').update(html).digest('hex');
const packageJson = JSON.parse(readFileSync(path.join(packageRoot, 'package.json'), 'utf8'));
const releaseVersionOverride = process.env.LODY_RELEASE_VERSION?.trim();
const version = releaseVersionOverride || packageJson.version;

if (typeof version !== 'string' || version.trim() === '') {
  throw new Error('The code review viewer requires a non-empty package version.');
}

mkdirSync(path.join(packageRoot, 'dist'), { recursive: true });
const banner = '// AUTO-GENERATED by scripts/build-viewer.mjs. Do not edit by hand.\n';
const body =
  `export const reviewViewerVersion = ${JSON.stringify(version)};\n` +
  `export const reviewViewerSha256 = ${JSON.stringify(sha256)};\n` +
  `export const reviewViewerFileName = 'standalone.html';\n`;
writeFileSync(path.join(packageRoot, 'dist/manifest.generated.ts'), banner + body, 'utf8');

console.log(
  `Built lody-code-review-viewer@${version}: standalone.html ` +
    `(${(html.length / 1024 / 1024).toFixed(2)} MB), sha256 ${sha256.slice(0, 12)}…`
);
